document.getElementById('start').addEventListener('click',resetGame);
function held(...names){return names.some(n=>keys.has(n))}
function circleHits(x,y,r){return x<r||y<r||x>WORLD-r||y>WORLD-r||buildings.some(b=>{const px=clamp(x,b.x,b.x+b.w),py=clamp(y,b.y,b.y+b.h);return (x-px)**2+(y-py)**2<r*r})}
function movePlayer(dx,dy,r){const ox=player.x,oy=player.y;player.x+=dx;if(circleHits(player.x,player.y,r))player.x=ox;player.y+=dy;if(circleHits(player.x,player.y,r))player.y=oy}
function interact(){
 if(player.car){player.car=false;player.speed=0;player.x+=Math.cos(player.angle+Math.PI/2)*25;player.y+=Math.sin(player.angle+Math.PI/2)*25;action('ON FOOT — E TO GET BACK IN')}
 else if(Math.hypot(player.x-safe.x,player.y-safe.y)<55){player.car=true;player.x=safe.x;player.y=safe.y;player.speed=0;action('BACK IN YOUR RIDE')}
 else action('NO RIDE CLOSE BY');
}
function spawnCop(){const a=rand()*Math.PI*2,r=270+rand()*90;let x=clamp(player.x+Math.cos(a)*r,40,WORLD-40),y=clamp(player.y+Math.sin(a)*r,40,WORLD-40);cops.push({x,y,a:Math.atan2(player.y-y,player.x-x),hit:0})}
function update(dt){
 now+=dt;player.invuln=Math.max(0,player.invuln-dt);if(shake>0)shake=Math.max(0,shake-dt);
 const up=held('KeyW','ArrowUp'),down=held('KeyS','ArrowDown'),left=held('KeyA','ArrowLeft'),right=held('KeyD','ArrowRight'),brake=held('Space'),boost=held('ShiftLeft','ShiftRight');
 if(player.car){
  const accel=boost?280:190,max=boost?365:285;
  if(up)player.speed=Math.min(max,player.speed+accel*dt);else if(down)player.speed=Math.max(-100,player.speed-accel*dt);else player.speed*=Math.pow(.972,dt*60);
  if(brake)player.speed*=Math.pow(.88,dt*60);
  const steer=(right?1:0)-(left?1:0);player.angle+=steer*dt*(.9+Math.min(1,Math.abs(player.speed)/110))*Math.sign(player.speed||1);
  const ox=player.x,oy=player.y;movePlayer(Math.cos(player.angle)*player.speed*dt,Math.sin(player.angle)*player.speed*dt,12);
  if(Math.abs(player.x-ox)+Math.abs(player.y-oy)<Math.abs(player.speed)*dt*.35){player.speed*=-.24;if(Math.abs(player.speed)>90){player.hp=Math.max(0,player.hp-4);shake=.18}}
 }else{
  let dx=(right?1:0)-(left?1:0),dy=(down?1:0)-(up?1:0),len=Math.hypot(dx,dy)||1;movePlayer(dx/len*155*dt,dy/len*155*dt,8);if(dx||dy)player.angle=Math.atan2(dy,dx);
 }
 for(const d of drops){if(!d.got&&dist(player,d)<34){d.got=true;player.money+=250;player.heat=Math.min(5,player.heat+1);action('DROP '+d.id+' SECURED  +$250',2.4);if(player.heat>=2&&cops.length<player.heat)spawnCop()}}
 if(drops.every(d=>d.got)&&dist(player,safe)<52){running=false;finish(true);return}
 for(let i=cops.length-1;i>=0;i--){const c=cops[i],a=Math.atan2(player.y-c.y,player.x-c.x);c.a=a;c.x+=Math.cos(a)*82*dt;c.y+=Math.sin(a)*82*dt;c.hit=Math.max(0,c.hit-dt);if(dist(c,player)<25&&c.hit===0){c.hit=1.5;player.hp=Math.max(0,player.hp-13);shake=.25;action('POLICE CLIPPED YOU!',1.4);if(player.hp<=0){running=false;finish(false);return}}}
 if(player.heat>0&&now>player.lastDrop+30){player.heat=Math.max(0,player.heat-dt*.025)}
 if(keys.has('KeyE')&&!player.eWas){interact()}player.eWas=keys.has('KeyE');
}
function finish(win){overlay.classList.remove('hidden');overlay.innerHTML=`<div class="panel"><div class="eyebrow">${win?'JOB COMPLETE':'BUSTED'}</div><h1 class="title">${win?'CLEAN<br><span>GETAWAY</span>':'NIGHT<br><span>OVER</span>'}</h1><p class="subtitle">${win?'Every drop delivered. The borough barely noticed.': 'The heat caught up with you. There is always another night.'}</p><div class="mission-card"><b style="color:#d5ff58">FINAL TAKE</b><br>${drops.filter(d=>d.got).length} / 5 drops secured &nbsp; · &nbsp; $${player.money.toLocaleString()} earned</div><button class="button" id="again">${win?'RUN IT BACK':'TRY AGAIN'} &nbsp; ↻</button></div><div class="stamp">NEON BOROUGH<br>AFTER HOURS</div>`;document.getElementById('again').onclick=resetGame}

