function box(x,y,w,h,color){ctx.fillStyle=color;ctx.fillRect(Math.round(x),Math.round(y),Math.round(w),Math.round(h))}
function worldDraw(){
 const camX=clamp(player.x-W/2,0,WORLD-W),camY=clamp(player.y-H/2,0,WORLD-H);ctx.save();if(shake)ctx.translate((rand()-.5)*shake*22,(rand()-.5)*shake*18);ctx.translate(-Math.round(camX),-Math.round(camY));
 box(camX,camY,W,H,'#344942');
 for(let i=0;i<180;i++){const x=(i*173+51)%WORLD,y=(i*317+83)%WORLD;box(x,y,2,2,i%3?'#3b5146':'#2e423e')}
 for(let i=0;i<7;i++){
  const p=ROAD0+i*STEP;
  box(p-ROAD/2,0,ROAD,WORLD,'#545958');box(0,p-ROAD/2,WORLD,ROAD,'#545958');
  box(p-ROAD/2-5,0,5,WORLD,'#85847b');box(p+ROAD/2,0,5,WORLD,'#85847b');box(0,p-ROAD/2-5,WORLD,5,'#85847b');box(0,p+ROAD/2,WORLD,5,'#85847b');
  for(let q=0;q<WORLD;q+=54){box(p-2,q,4,22,'#77766d');box(q,p-2,22,4,'#77766d')}
 }
 for(const d of decor){if(d.type==='tree'){box(d.x-3,d.y+3,7,9,'#263831');box(d.x-7,d.y-5,15,12,'#617c54');box(d.x-4,d.y-7,8,7,'#789060')}else{box(d.x-1,d.y-9,2,16,'#aaa28a');box(d.x-3,d.y-11,6,3,'#e7cc88')}}
 for(const b of buildings){box(b.x+5,b.y+7,b.w,b.h,'#263331');box(b.x,b.y,b.w,b.h,b.c);box(b.x+2,b.y+2,b.w-4,b.h-4,b.roof);box(b.x+5,b.y+5,b.w-10,3,'#a69b83');box(b.x+b.w*.4,b.y+b.h*.39,b.w*.22,b.h*.2,'#77796f')}
 for(const w of windows)if(w.on)box(w.x,w.y,5,7,'#d7c080');
 // Safehouse garage
 box(safe.x-25,safe.y+34,50,5,'#d5ff58');box(safe.x-25,safe.y+40,50,3,'#182321');box(safe.x-18,safe.y+23,36,13,'#33433c');box(safe.x-13,safe.y+26,26,10,'#202a28');
 for(const d of drops)if(!d.got){const pulse=1+Math.floor((Math.sin(now*5+d.id)+1)*1.5);ctx.strokeStyle='#d5ff58';ctx.lineWidth=2;ctx.strokeRect(d.x-8-pulse,d.y-8-pulse,16+pulse*2,16+pulse*2);box(d.x-3,d.y-3,6,6,'#efff9a');box(d.x-2,d.y-1,4,2,'#677e27')}
 for(const c of cops)drawCar(c.x,c.y,c.a,'#dfe5df',true);
 if(player.car)drawCar(player.x,player.y,player.angle,'#e8a84e',false);else drawPerson(player.x,player.y,player.angle);
 ctx.restore();return {camX,camY};
}
function drawCar(x,y,a,color,police){ctx.save();ctx.translate(Math.round(x),Math.round(y));ctx.rotate(a);box(-16,-11,32,23,'#202729');box(-13,-12,26,24,color);box(-8,-9,15,18,police?'#596767':'#60757a');box(7,-8,5,16,police?'#b8c5c5':'#eec986');box(-13,-8,3,5,'#f8e9ba');box(-13,4,3,5,'#f27c63');box(-14,-14,7,3,'#171c1d');box(7,-14,7,3,'#171c1d');box(-14,11,7,3,'#171c1d');box(7,11,7,3,'#171c1d');if(police){box(-3,-13,7,3,'#f25063');box(1,-13,5,3,'#4ba9e8')}ctx.restore()}
function drawPerson(x,y,a){ctx.save();ctx.translate(Math.round(x),Math.round(y));ctx.rotate(a);box(-4,-3,9,10,'#202627');box(-4,-5,8,9,'#e8a84e');box(-3,-8,6,6,'#d7a47c');box(1,-7,4,2,'#d7ff70');ctx.restore()}

